R=Path(__file__).resolve().parents[2];p=Path(__file__).with_name('front_sections_pixel_candidates.json');j=json.loads(p.read_text());section=next(v for v in j['profiles'] if v['section']=='A');poly=np.array(section['loops_pixel'][0],dtype=float)
